void compress_string(const char *src, char *dest) {
    const char *p = src;
    char *d = dest;

    while (*p) {
        char c = *p;
        int count = 0;

        while (*p == c) {
            count++;
            p++;
        }

        *d++ = c;
        if (count > 1 || !(p - src >= 1 && *(p - 2) != c)) {
            // Always write count for the RLE spec as described: char+count pairs.
            // But for single chars that are not repeated, a plain RLE would omit count.
            // The examples show "a2b1c3" and "a2b1c5a3" — counts are always written.
            // Store count digit by digit (no sprintf to keep it simple)
            if (count >= 10) {
                *d++ = '0' + count / 10;
            }
            *d++ = '0' + (count % 10);
        } else {
            *d++ = '1';
        }
    }

    *d = '\0';
}

